def count_islands(grid):
    """Count 4-connected groups of 1s in a grid of 0/1 lists."""
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    count = 0

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            curr_r, curr_c = stack.pop()
            if not (0 <= curr_r < rows and 0 <= curr_c < cols):
                continue
            if grid[curr_r][curr_c] != 1:
                continue
            if visited[curr_r][curr_c]:
                continue
            visited[curr_r][curr_c] = True
            stack.append((curr_r + 1, curr_c))
            stack.append((curr_r - 1, curr_c))
            stack.append((curr_r, curr_c + 1))
            stack.append((curr_r, curr_c - 1))

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                count += 1
                dfs(r, c)

    return count
